<?php $edit=!empty($sancion['id_sancion']); $titulo=$edit?'Editar sanción':'Nueva sanción'; require __DIR__.'/../partials/header.php'; ?>
<div class="form-page"><div class="section-title"><h1><?php echo $titulo; ?></h1><a href="index.php?url=sanciones">Cancelar</a></div><?php if($error): ?><div class="alert alert-error"><?php echo htmlspecialchars($error); ?></div><?php endif; ?>
<form class="card form-grid" method="POST" action="index.php?url=<?php echo $edit?'sanciones-actualizar':'sanciones-guardar'; ?>"><?php echo Csrf::input(); ?><?php if($edit): ?><input type="hidden" name="id_sancion" value="<?php echo (int)$sancion['id_sancion']; ?>"><?php endif; ?>
<div class="full"><label>Estudiante *</label><select name="id_estudiante" required><option value="">Seleccione...</option><?php foreach($catalogos['estudiantes'] as $e): ?><option value="<?php echo $e['id_estudiante']; ?>" <?php echo isset($sancion['id_estudiante'])&&$sancion['id_estudiante']==$e['id_estudiante']?'selected':''; ?>><?php echo htmlspecialchars($e['codigo_estudiante'].' · '.$e['apellidos'].' '.$e['nombres']); ?></option><?php endforeach; ?></select></div>
<div><label>Tipo de sanción *</label><select name="id_tipo" required><option value="">Seleccione...</option><?php foreach($catalogos['tipos'] as $t): ?><option value="<?php echo $t['id_tipo']; ?>" <?php echo isset($sancion['id_tipo'])&&$sancion['id_tipo']==$t['id_tipo']?'selected':''; ?>><?php echo htmlspecialchars($t['nombre'].' ('.$t['puntos'].' puntos)'); ?></option><?php endforeach; ?></select></div>
<div><label>Gestión *</label><select name="id_gestion" required><?php foreach($catalogos['gestiones'] as $g): ?><option value="<?php echo $g['id_gestion']; ?>" <?php echo isset($sancion['id_gestion'])&&$sancion['id_gestion']==$g['id_gestion']?'selected':''; ?>><?php echo $g['gestion']; ?></option><?php endforeach; ?></select></div>
<div><label>Fecha *</label><input type="date" name="fecha_sancion" value="<?php echo htmlspecialchars(isset($sancion['fecha_sancion'])?$sancion['fecha_sancion']:date('Y-m-d')); ?>" required></div><div></div>
<div class="full"><label>Descripción de la conducta *</label><textarea name="descripcion" rows="5" required><?php echo htmlspecialchars(isset($sancion['descripcion'])?$sancion['descripcion']:''); ?></textarea></div><div class="full"><label>Acción tomada</label><textarea name="accion_tomada" rows="3"><?php echo htmlspecialchars(isset($sancion['accion_tomada'])?$sancion['accion_tomada']:''); ?></textarea></div><div class="full"><button><?php echo $edit?'Actualizar sanción':'Registrar sanción'; ?></button></div></form></div>
<?php require __DIR__.'/../partials/footer.php'; ?>
